<section class="<?= c('home', 'about') ?>" aria-labelledby="about-title"><span class="<?= c('home', 'eyebrow') ?>">{Обо мне}</span><h2 id="about-title"><?= t($site['aboutTitle']) ?></h2><p><?= t($site['aboutText']) ?></p><div class="<?= c('home', 'stats') ?>"><?php foreach ($site['stats'] as $index => $stat): ?><article><strong><?= h($stat['value']) ?></strong><span><?= t($stat['label']) ?></span><i aria-hidden="true"><?php for ($star = 0; $star < 3; $star++) image('/assets/figma/logo' . ($star <= $index ? 2 : 3) . '.svg', '', ['width' => 20, 'height' => 20]); ?></i></article><?php endforeach; ?></div></section>
<section class="<?= c('home', 'portfolio') ?>" id="portfolio" aria-labelledby="portfolio-title"><div class="<?= c('home', 'greenTexture') ?>" aria-hidden="true"></div><div class="<?= c('home', 'portfolioInner') ?>"><?php section_title('Лучшие проекты', $site['portfolioTitle'], 'portfolio-title'); ?><div class="<?= c('home', 'portfolioGallery') ?>"><?php foreach ($featured as $project) project_card($project); ?></div><div class="<?= c('home', 'projectRows') ?>"><?php foreach ($listed as $project) project_row($project); ?></div><?php all_projects(count(array_filter($site['portfolioProjects'], fn(array $project): bool => $project['portfolioPlacement'] !== 'hidden')), c('home', 'allProjects')); ?></div></section>
