<?php if ($index === 3): ?><div class="<?= c('home', 'processOptions') ?>"><div class="<?= c('home', 'processOption') ?>"><h4><?php image('/assets/figma/platform.svg', '', ['width' => 28, 'height' => 28]); ?><?= t('Разработка на Tilda') ?></h4><p><?= t('Собираю сайт по макетам: адаптив, анимации, формы и базовые интеграции. Проверяю на разных устройствах и готовлю к публикации.') ?></p></div><?php if (!empty($step['secondaryTitle'])): ?><div class="<?= c('home', 'processOption') ?>"><h4><?php image('/assets/figma/image36-vectorized.svg', '', ['width' => 28, 'height' => 28]); ?><?= t($step['secondaryTitle']) ?></h4><p><?= t($step['secondaryText'] ?? '') ?></p></div><?php endif; ?></div><?php endif; ?><?php if (trim($step['result'] ?? '') !== ''): ?><div class="<?= c('home', 'stepResult') ?>"><span>Что получаете</span><p><?= t($step['result']) ?></p></div><?php endif; ?></div><div class="<?= c('home', 'stepMedia') ?>"><div><?php image($step['image'], '', [], true); ?></div><?php if (!empty($step['secondaryImage'])): ?><div><?php image($step['secondaryImage'], '', [], true); ?></div><?php endif; ?></div></article><?php endforeach; ?></div></div></section>
